CREATE TABLE IF NOT EXISTS vehicles (id BIGSERIAL PRIMARY KEY, stock_number TEXT NOT NULL UNIQUE, make TEXT NOT NULL, model TEXT NOT NULL, year INTEGER NOT NULL, trim TEXT DEFAULT '', price NUMERIC(12,2) NOT NULL DEFAULT 0, cost NUMERIC(12,2) NOT NULL DEFAULT 0, mileage INTEGER DEFAULT 0, color TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Available' CHECK (status IN ('Available','Reserved','Sold','Service')), image_url TEXT DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT DEFAULT '', phone TEXT DEFAULT '', source TEXT DEFAULT 'Walk-in', notes TEXT DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('income','expense')), category TEXT NOT NULL, description TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount >= 0), entry_date DATE NOT NULL DEFAULT CURRENT_DATE, customer_id BIGINT REFERENCES customers(id) ON DELETE SET NULL, vehicle_id BIGINT REFERENCES vehicles(id) ON DELETE SET NULL, payment_method TEXT DEFAULT 'Other', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sales (id BIGSERIAL PRIMARY KEY, invoice_number TEXT NOT NULL UNIQUE, vehicle_id BIGINT REFERENCES vehicles(id) ON DELETE SET NULL, customer_id BIGINT REFERENCES customers(id) ON DELETE SET NULL, sale_price NUMERIC(12,2) NOT NULL, sale_date DATE NOT NULL DEFAULT CURRENT_DATE, notes TEXT DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS transactions_date_idx ON transactions(entry_date DESC);
CREATE INDEX IF NOT EXISTS vehicles_status_idx ON vehicles(status);
